with parsed as (select id, plan, tier_prices, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, array_min(tier_prices) as lowest_price, element_at(tier_prices, 1) as entry_price from price_tiers) select id, plan, lowest_price, sum(lowest_price) over (partition by plan order by avg_tier_price, id rows between unbounded preceding and current row) as running_lowest_price, rank() over (partition by plan order by lowest_price desc nulls last) as lowest_price_rank, ntile(5) over (partition by plan order by avg_tier_price desc, id) as avg_tier_price_bucket, last_value(entry_price) ignore nulls over (order by lowest_price, id rows between unbounded preceding and current row) as last_known_entry_price, lead(avg_tier_price, 1) over (partition by plan order by avg_tier_price, id) as next_avg_tier_price from parsed;
